import type { ReachLevel } from "@/features/admin/domain/role-reach";
import { cn } from "@/lib/cn";

/**
 * Literal class strings, one per level. A height interpolated into a class name is never
 * generated by Tailwind, and the only symptom is a glyph that silently draws nothing.
 *
 * Neutral ink: on this rail the brand colour already means "this row is selected", so a glyph
 * carrying it on every row left nothing to recede.
 */
const BAR: Record<ReachLevel, string> = {
  none: "h-[3px] bg-border-strong",
  some: "h-[9px] bg-muted-foreground/55",
  all: "h-4 bg-muted-foreground",
};

/** The selected row, and only it, carries the accent. */
const SELECTED_BAR: Record<ReachLevel, string> = {
  none: "h-[3px] bg-primary/35",
  some: "h-[9px] bg-primary/60",
  all: "h-4 bg-primary",
};

/**
 * A role's silhouette: one bar per applicable permission group, its height showing how deep
 * the role reaches into that group. Hidden from assistive technology because the rail row it
 * sits in already carries the same fact in words.
 */
export function ReachGlyph({
  levels,
  selected = false,
}: Readonly<{ levels: ReachLevel[]; selected?: boolean }>) {
  const bar = selected ? SELECTED_BAR : BAR;
  return (
    <span aria-hidden="true" className="flex h-4 shrink-0 items-end gap-0.5">
      {levels.map((level, i) => (
        <span
          // Position in the catalog is the identity here: the groups are a fixed ordered
          // list, so nothing reorders and the index is stable.
          key={i}
          className={cn(
            "w-[3px] rounded-[1px] motion-safe:transition-[height] motion-safe:duration-300",
            bar[level],
          )}
        />
      ))}
    </span>
  );
}
